reset role;
create temp table inventory_fixture(tag text,id uuid);
insert into inventory_fixture values ('draft',test_fixtures.listing('11111111-1111-4111-8111-111111111111','draft'));
insert into inventory_fixture values ('pending',test_fixtures.listing('11111111-1111-4111-8111-111111111111','pending'));
insert into inventory_fixture values ('rejected',test_fixtures.listing('11111111-1111-4111-8111-111111111111','rejected'));
insert into inventory_fixture values ('active',test_fixtures.listing('11111111-1111-4111-8111-111111111111','active'));
insert into inventory_fixture values ('reserved',test_fixtures.listing('11111111-1111-4111-8111-111111111111','reserved'));
insert into inventory_fixture values ('sold',test_fixtures.listing('11111111-1111-4111-8111-111111111111','sold'));
insert into inventory_fixture values ('archived',test_fixtures.listing('11111111-1111-4111-8111-111111111111','archived'));
insert into inventory_fixture values ('removed',test_fixtures.listing('11111111-1111-4111-8111-111111111111','removed'));
