update public.listings set category='rackets',status='traded',offer_type='swap',price_egp=null,balls_quantity_packaging=null,swap_preference='Control racket',racket_damage_repair_disclosure='None' where id=(select id from inventory_fixture where tag='traded');
insert into public.listings(seller_id,category) select seller_id,'shoes' from public.listings limit 1;
insert into inventory_fixture select 'blank',id from public.listings where title is null;
insert into inventory_fixture select 'extra',test_fixtures.listing('11111111-1111-4111-8111-111111111111','draft') from generate_series(1,20);
update public.listings set created_at='2026-11-01',updated_at='2026-11-02';
update public.listings set submitted_at='2026-10-01' where status='pending';
grant select on inventory_fixture to authenticated,anon;
set local role anon;
set local request.jwt.claims='{"sub":"22222222-2222-4222-8222-222222222222","aal":"aal2","session_id":"00000000-0000-4000-8000-000000000001","amr":[{"method":"password","timestamp":1795000000},{"method":"totp","timestamp":1795000001}]}';
select throws_ok($$select public.admin_listing_inventory()$$,'42501',null,'anonymous denied public.admin_listing_inventory');
select throws_ok($$select public.admin_listing_inspection((select id from inventory_fixture where tag='draft'))$$,'42501',null,'anonymous denied public.admin_listing_inspection');
