set local request.jwt.claims='{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","aal":"aal1","session_id":"00000000-0000-4000-8000-000000000001","amr":[{"method":"password","timestamp":1795000000},{"method":"totp","timestamp":1795000001}]}';
select throws_ok($$select public.admin_listing_inventory()$$,'42501',null,'admin without MFA denied public.admin_listing_inventory');
select throws_ok($$select public.admin_listing_inspection((select id from inventory_fixture where tag='draft'))$$,'42501',null,'admin without MFA denied public.admin_listing_inspection');
