select is(public.admin_listing_inventory(p_status=>'draft')->>'total','22','draft filter includes supported lifecycle state');
select is(public.admin_listing_inventory(p_status=>'pending')->>'total','1','pending filter includes supported lifecycle state');
select is(public.admin_listing_inventory(p_status=>'rejected')->>'total','1','rejected filter includes supported lifecycle state');
select is(public.admin_listing_inventory(p_status=>'active')->>'total','1','active filter includes supported lifecycle state');
select is(public.admin_listing_inventory(p_status=>'reserved')->>'total','1','reserved filter includes supported lifecycle state');
select is(public.admin_listing_inventory(p_status=>'sold')->>'total','1','sold filter includes supported lifecycle state');
select is(public.admin_listing_inventory(p_status=>'traded')->>'total','1','traded filter includes supported lifecycle state');
select is(public.admin_listing_inventory(p_status=>'archived')->>'total','1','archived filter includes supported lifecycle state');
select is(public.admin_listing_inventory(p_status=>'removed')->>'total','1','removed filter includes supported lifecycle state');
select is(public.admin_listing_inventory(p_sort=>'updated')->'items',public.admin_listing_inventory(p_sort=>'created')->'items','equal timestamp ties use stable UUID ordering');
select is(public.admin_listing_inventory()->>'total','30','all supported states and incomplete draft counted');
select is(jsonb_array_length(public.admin_listing_inventory()->'items'),24,'bounded first page');
select is(jsonb_array_length(public.admin_listing_inventory(p_page=>2)->'items'),6,'remaining second page');
select is(public.admin_listing_inventory()->'items',public.admin_listing_inventory()->'items','stable tied ordering');
select ok(not exists(select 1 from jsonb_array_elements(public.admin_listing_inventory()->'items') a join jsonb_array_elements(public.admin_listing_inventory(p_page=>2)->'items') b on a->>'id'=b->>'id'),'pages never overlap');
select is(public.admin_listing_inventory(p_query=>'inventory_owner')->>'total','30','seller username search');
select is(public.admin_listing_inventory(p_query=>'Synthetic Inventory Owner')->>'total','30','seller display name search');
select is(public.admin_listing_inventory(p_query=>'HEAD')->>'total','29','case insensitive brand search');
select is(public.admin_listing_inventory(p_query=>'Test')->>'total','29','model search');
select is(public.admin_listing_inventory(p_query=>'Synthetic balls')->>'total','29','title search');
select is(public.admin_listing_inventory(p_query=>(select id::text from inventory_fixture where tag='blank'))->>'total','1','exact UUID search');
select is(public.admin_listing_inventory(p_query=>'%')->>'total','0','wildcards are literal');
select is(public.admin_listing_inventory(p_status=>'pending',p_category=>'balls',p_account_type=>'individual',p_governorate=>'giza')->>'total','1','combined filters');
select is(public.admin_listing_inventory(p_account_type=>'business')->>'total','0','empty filtered count');
select is(public.admin_listing_inventory(p_sort=>'pending')->'items'->0->>'status','pending','pending submission ordered first');
select is(public.admin_listing_inventory()->'counts'->>'draft','22','unfiltered status counts');
select is(public.admin_listing_inspection((select id from inventory_fixture where tag='blank'))->'listing'->>'title',null,'incomplete draft inspected');
select is(public.admin_listing_inspection((select id from inventory_fixture where tag='active'))->'inspection'->>'public_visible','false','active is not necessarily public');
select throws_ok($$select public.admin_listing_inventory(p_page=>0)$$,'22023',null,'invalid p_page=>0 denied');
select throws_ok($$select public.admin_listing_inventory(p_page=>10001)$$,'22023',null,'invalid p_page=>10001 denied');
select throws_ok($$select public.admin_listing_inventory(p_page=>null)$$,'22023',null,'invalid p_page=>null denied');
select throws_ok($$select public.admin_listing_inventory(p_query=>repeat('a',121))$$,'22023',null,'invalid p_query=>repeat(a,121) denied');
select throws_ok($$select public.admin_listing_inventory(p_query=>null)$$,'22023',null,'invalid p_query=>null denied');
select throws_ok($$select public.admin_listing_inventory(p_status=>'bad')$$,'22023',null,'invalid p_status=>bad denied');
select throws_ok($$select public.admin_listing_inventory(p_category=>'bad')$$,'22023',null,'invalid p_category=>bad denied');
select throws_ok($$select public.admin_listing_inventory(p_account_type=>'admin')$$,'22023',null,'invalid p_account_type=>admin denied');
select throws_ok($$select public.admin_listing_inventory(p_governorate=>'bad')$$,'22023',null,'invalid p_governorate=>bad denied');
select throws_ok($$select public.admin_listing_inventory(p_sort=>'bad')$$,'22023',null,'invalid p_sort=>bad denied');
select lives_ok($$select public.admin_approve_listing((select id from inventory_fixture where tag='pending'),1,1,3,public.admin_get_listing_review((select id from inventory_fixture where tag='pending'))->'media_manifest')$$,'pending approval reused');
select is(public.admin_listing_inspection((select id from inventory_fixture where tag='pending'))->'inspection'->>'public_visible','true','approved snapshot public');
select throws_ok($$select public.admin_remove_listing((select id from inventory_fixture where tag='pending'),2,1,3,public.admin_get_listing_review((select id from inventory_fixture where tag='pending'))->'media_manifest','')$$,'22023',null,'empty reason denied');
select throws_ok($$select public.admin_remove_listing((select id from inventory_fixture where tag='pending'),1,1,3,public.admin_get_listing_review((select id from inventory_fixture where tag='pending'))->'media_manifest','reason')$$,'PT409',null,'stale listing denied');
select throws_ok($$select public.admin_remove_listing((select id from inventory_fixture where tag='pending'),2,2,3,public.admin_get_listing_review((select id from inventory_fixture where tag='pending'))->'media_manifest','reason')$$,'PT409',null,'stale content denied');
select throws_ok($$select public.admin_remove_listing((select id from inventory_fixture where tag='pending'),2,1,2,public.admin_get_listing_review((select id from inventory_fixture where tag='pending'))->'media_manifest','reason')$$,'PT409',null,'stale profile denied');
select throws_ok($$select public.admin_remove_listing((select id from inventory_fixture where tag='pending'),2,1,3,'[]','reason')$$,'PT409',null,'stale media denied');
select throws_ok($$select public.admin_remove_listing((select id from inventory_fixture where tag='draft'),1,1,3,public.admin_get_listing_review((select id from inventory_fixture where tag='draft'))->'media_manifest','reason')$$,'PT409',null,'draft removal denied');
select lives_ok($$select public.admin_remove_listing((select id from inventory_fixture where tag='pending'),2,1,3,public.admin_get_listing_review((select id from inventory_fixture where tag='pending'))->'media_manifest','Synthetic removal')$$,'public listing removed');
select is(public.admin_listing_inspection((select id from inventory_fixture where tag='pending'))->'listing'->>'status','removed','removed status');
select is(public.admin_listing_inspection((select id from inventory_fixture where tag='pending'))->'inspection'->>'public_visible','false','public eligibility revoked');
select is(public.get_public_listing((select id from inventory_fixture where tag='pending')),null,'public detail revoked');
select is(public.admin_listing_inspection((select id from inventory_fixture where tag='pending'))->'inspection'->'decision'->>'reason','Synthetic removal','latest removal reason visible');
reset role;
select is((select count(*)::integer from private.audit_logs where action='listing.removed'),1,'exactly one audit record');
select is((select after_state->>'version' from private.audit_logs where action='listing.removed'),'3','audit version recorded');
select is((select count(*)::integer from public.listing_media where listing_id=(select id from inventory_fixture where tag='pending')),3,'photos retained');
select ok(not has_table_privilege('authenticated','public.listings','SELECT'),'no direct inventory table grant');
update private.admin_roles set revoked_at=now();
set local role authenticated;
set local request.jwt.claims='{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","aal":"aal2","session_id":"00000000-0000-4000-8000-000000000001","amr":[{"method":"password","timestamp":1795000000},{"method":"totp","timestamp":1795000001}]}';
select throws_ok($$select public.admin_listing_inventory()$$,'42501',null,'revoked admin denied');
select throws_ok($$select public.admin_listing_inspection((select id from inventory_fixture where tag='draft'))$$,'42501',null,'revoked admin denied');
select throws_ok($$select public.admin_photo_delivery((select id from inventory_fixture where tag='draft'),gen_random_uuid())$$,'42501',null,'revoked admin denied');
reset role;
select * from finish();
rollback;
